<?php
namespace App\Console\Commands\Commercial;use App\Models\Tenant;use Illuminate\Console\Command;use Illuminate\Support\Facades\Artisan;use Illuminate\Support\Facades\Cache;use Illuminate\Support\Facades\File;use Throwable;
class UpdatePromptBotCommand extends Command{protected $signature='promptbot:update {--confirm : Confirm a verified backup exists}';protected $description='Safely apply central and tenant migrations for a PromptBot release';public function handle():int{if(!$this->option('confirm')){$this->error('Create and verify database and uploaded-file backups, then rerun with --confirm.');return self::FAILURE;}return Cache::lock('promptbot-commercial-update',3600)->block(5,function():int{$this->info('Enabling maintenance mode...');Artisan::call('down',['--retry'=>60]);try{Artisan::call('migrate',['--force'=>true]);foreach(Tenant::cursor() as $tenant){$this->line("Migrating tenant {$tenant->id}");tenancy()->initialize($tenant);Artisan::call('migrate',['--database'=>'tenant','--path'=>'database/migrations/tenant','--force'=>true]);Artisan::call('db:seed',['--class'=>'Database\\Seeders\\TenantAuthorizationSeeder','--force'=>true]);tenancy()->end();}Artisan::call('optimize:clear');Artisan::call('optimize');File::put(storage_path('app/last-update.json'),json_encode(['version'=>config('promptbot.version'),'completed_at'=>now()->toIso8601String()],JSON_PRETTY_PRINT));$this->info('Update completed: '.config('promptbot.version'));return self::SUCCESS;}catch(Throwable $e){report($e);$this->error($e->getMessage());return self::FAILURE;}finally{if(tenancy()->initialized)tenancy()->end();Artisan::call('up');}});}}
